D = math.radians


def s2l(c):
    """sRGB -> linear; Blender colour sockets are linear."""
    return c / 12.92 if c <= 0.04045 else ((c + 0.055) / 1.055) ** 2.4


def M(name, color, metallic=0.0, rough=0.45, alpha=1.0, transmission=0.0):
    """color is given in sRGB (what the eye sees), stored linear."""
    m = bpy.data.materials.get(name)
    if m is None:
        m = bpy.data.materials.new(name)
    m.use_nodes = True
    bsdf = m.node_tree.nodes.get("Principled BSDF")

    def put(names, val):
        for n in names:
            if n in bsdf.inputs:
                bsdf.inputs[n].default_value = val
                return

    put(["Base Color"], (s2l(color[0]), s2l(color[1]), s2l(color[2]), 1.0))
